/**
 * ingest が原本をコミットする tx の中で recording_encode_policy 行の
 * INSERT として焼かれる（凍結される）瞬間まで効く。録画開始後の変更でも、
 * 放送終了・ingest 完了より前ならこの録画に反映されるが、ingest 完了後の
 * 変更はこの録画には反映されない（docs/recording/reservation-model.md
 * §4.5）。
 *
 * **「ingest 完了より前なら必ず反映される」ではない** --- 凍結の導出元
 * （program_snapshots と CASCADE で連なる予約系の表）は放送終了 +
 * `epg.retention_grace`（既定 24h）で GC されるため、エッジに record が
 * 滞留して ingest がそれを超えて遅れると、指定は効かず既定値
 * （keepOriginal=always / encodeProfiles=[]）で凍結される（原本は残る
 * がエンコードは投入されない。docs/storage/retention.md §6「凍結が
 * 依存する寿命と、エッジの滞留の交点」）。
 */
export type ProgramOverridesInputKeepOriginal = typeof ProgramOverridesInputKeepOriginal[keyof typeof ProgramOverridesInputKeepOriginal];


export const ProgramOverridesInputKeepOriginal = {
  always: 'always',
  until_encoded: 'until_encoded',
} as const;

export type ProgramOverridesInputResetItem = typeof ProgramOverridesInputResetItem[keyof typeof ProgramOverridesInputResetItem];


export const ProgramOverridesInputResetItem = {
  priority: 'priority',
  contentPath: 'contentPath',
  filenameTemplate: 'filenameTemplate',
  keepOriginal: 'keepOriginal',
  encodeProfiles: 'encodeProfiles',
} as const;

/**
 * PATCH /api/sites/{site}/programs/{programId}/overrides のボディ。
 * 値を書いたフィールドは override を設定し、`reset` に名前を挙げた
 * フィールドは override を削除する。どちらにも現れないフィールドは
 * 変更しない。同じフィールドを値と `reset` の両方に書いたら 400、
 * `reset` に未知のフィールド名があっても 400（docs/recording.md §4.2）。
 */
export interface ProgramOverridesInput {
  /**
     * mirakc の schedule に反映される（reconciler が DELETE + POST で
     * schedule を再作成する）。ただし録画開始後の recorder には
     * 効かない可能性が高い（docs/recording.md §4.5）。
     */
  priority?: number;
  /**
     * 明示指定した値は既存の schedule にも反映される（reconciler が
     * DELETE + POST で張り替える）。ただし録画が始まった schedule には
     * 反映されない（docs/recording.md §4.5）。空文字は 400（override を
     * 消すのは `reset`。消しても既存 schedule のパスは変わらない）。
     */
  contentPath?: string;
  /**
     * Go text/template のテンプレート文字列。既存の schedule には
     * 反映されず、まだ schedule が作られていない予約にだけ効く
     * （docs/recording.md §4.5）。`contentPath` を明示指定すればそちらは
     * 既存の schedule にも反映される（このフィールドとの違い）。
     */
  filenameTemplate?: string;
  /**
     * ingest が原本をコミットする tx の中で recording_encode_policy 行の
     * INSERT として焼かれる（凍結される）瞬間まで効く。録画開始後の変更でも、
     * 放送終了・ingest 完了より前ならこの録画に反映されるが、ingest 完了後の
     * 変更はこの録画には反映されない（docs/recording/reservation-model.md
     * §4.5）。
     *
     * **「ingest 完了より前なら必ず反映される」ではない** --- 凍結の導出元
     * （program_snapshots と CASCADE で連なる予約系の表）は放送終了 +
     * `epg.retention_grace`（既定 24h）で GC されるため、エッジに record が
     * 滞留して ingest がそれを超えて遅れると、指定は効かず既定値
     * （keepOriginal=always / encodeProfiles=[]）で凍結される（原本は残る
     * がエンコードは投入されない。docs/storage/retention.md §6「凍結が
     * 依存する寿命と、エッジの滞留の交点」）。
     */
  keepOriginal?: ProgramOverridesInputKeepOriginal;
  /**
     * ingest が原本をコミットする tx の中で recording_encode_policy 行の
     * INSERT として焼かれる（凍結される）瞬間まで効く。録画開始後の変更でも、
     * 放送終了・ingest 完了より前ならこの録画に反映されるが、ingest 完了後の
     * 変更はこの録画には反映されない（docs/recording/reservation-model.md
     * §4.5）。
     *
     * **「ingest 完了より前なら必ず反映される」ではない** --- 凍結の導出元
     * （program_snapshots と CASCADE で連なる予約系の表）は放送終了 +
     * `epg.retention_grace`（既定 24h）で GC されるため、エッジに record が
     * 滞留して ingest がそれを超えて遅れると、指定は効かず既定値
     * （keepOriginal=always / encodeProfiles=[]）で凍結される（原本は残る
     * がエンコードは投入されない。docs/storage/retention.md §6「凍結が
     * 依存する寿命と、エッジの滞留の交点」）。
     */
  encodeProfiles?: string[];
  /**
     * 指定したフィールドの override を削除する（フィールド単位の
     * 「ルールに戻す」）。値を書いたフィールドと重複して指定すると 400。
     */
  reset?: ProgramOverridesInputResetItem[];
}

