    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof searchPrograms>>, TError,SearchProgramsMutationVariables, TContext>, request?: SecondParameter<typeof customInstance>}
): UseMutationOptions<Awaited<ReturnType<typeof searchPrograms>>, TError,SearchProgramsMutationVariables, TContext> => {

const mutationKey = getSearchProgramsMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof searchPrograms>>, SearchProgramsMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  searchPrograms(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type SearchProgramsMutationResult = NonNullable<Awaited<ReturnType<typeof searchPrograms>>>
    export type SearchProgramsMutationBody = ProgramSearchRequest
    export type SearchProgramsMutationError = ErrorResponse
    export type SearchProgramsMutationVariables = {data: ProgramSearchRequest}

    /**
 * @summary Search EPG programs by rule-style conditions
 */
