    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof searchPrograms>>, TError,SearchProgramsMutationVariables, TContext>, request?: SecondParameter<typeof customInstance>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof searchPrograms>>,
        TError,
        SearchProgramsMutationVariables,
        TContext
      > => {
      return useMutation(getSearchProgramsMutationOptions(options), queryClient);
    }

